    """Trace the 3x3 motif instructions from the marker on a 7-column canvas."""
    h = len(grid)
    out = [[0] * 7 for _ in range(h)]

    # The color-5 marker starts the trace; its horizontal offset from the
    # divider determines the starting column on the output canvas.
    marker = next(
        ( (r, c) for r, row in enumerate(grid)
          for c, value in enumerate(row) if value == 5 ),
        None,
    )
    if marker is None:
        raise ValueError("grid has no color-5 start marker")
    _, marker_col = marker
    x = marker_col - 8
    y = 0
    if not (0 <= x < 7):
        raise ValueError("marker is not at the expected offset from the divider")
    out[y][x] = 5
    y = 1

    # Instructions are arranged as two vertical motif columns, each made of
    # 3-row tiles separated by a blank row (with the color-4 divider between).
    instructions = []
    for panel_start in (0, 4):
        for top in range(0, h, 4):
            colors = {
                grid[r][c]
                for r in range(top, min(top + 3, h))
                for c in range(panel_start, panel_start + 3)
                if c < len(grid[r]) and grid[r][c] not in (0, 4, 5)
            }
            if colors:
                if len(colors) != 1:
                    raise ValueError("motif tile contains multiple instruction colors")
                instructions.append(next(iter(colors)))

    # Each instruction draws a straight colored stroke from the current
    # horizontal position. Horizontal strokes consume one row; color 6
    # consumes two rows vertically.
    for color in instructions:
        if color == 1:
            cells = range(x, x + 3)
            if y >= h or x + 2 >= 7:
                break
            for c in cells:
                out[y][c] = color
            x += 2
            y += 1
        elif color == 2:
            if y >= h or x - 1 < 0:
